          setCompletedSteps(prev => new Set([...prev, currentStep]));
          setMyPhone(formData.phone_number || '0712345678');

          const partialUser = {
            phone: formData.phone_number || phone || '0712345678',
            name: formData.name || 'User',
            age: formData.age || '26',
            town: formData.town || 'Nairobi',
            county: formData.county || 'Nairobi'
          };
          setCurrentUser(partialUser);
          setShowMainMenu(true);
          setIsLoading(false);
          setRegistrationError('⚠️ User already exists. You can proceed to find matches.');
          return;
        }

        if (result && result.status === 'success') {
          const userMsg = step.userMessage(formData);
          const sysMsg = result.message || step.systemMessage(formData);
          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setMyPhone(formData.phone_number || '0712345678');
